import { useEffect, useState } from 'react';

// Same pre-rasterised shells the LCD draws (public/bubbles, generated by tools_make_bubbles.py), with sample text laid out in each shell's measured text rectangle.
type Meta = Record<string, { w: number; h: number; text: [number, number, number, number]; fill: string }>;
const STYLES: [string, string, string, string, string?][] = [
  ['cloud', 'Working', 'Claude · 작업 중...', '키보드 웹 UI 수정 중...'],
  ['burst', 'Done', 'BLE 연결 오류 수정 완료', 'Claude · Swift 빌드 통과'],
  ['spiky', 'Approval', '승인이 필요해!', 'Codex · 명령 실행 허용'],
  ['shaky', 'Error', '오류 발생', 'Claude · 빌드 실패'],
  ['soft', 'Gmail', '프로젝트 회의록 공유드립니다', 'Gmail · 김하은'],
  ['star', 'Lunch', '소곤면옥 대치직영점', 'Lunch · 한식 · 241 m'],
];
const SCALE = 1.5;

function Shell({ name, size, title, body }: { name: string; size: 'full' | 'half'; title: string; body: string }) {
  const [meta, setMeta] = useState<Meta | null>(null);
  useEffect(() => { fetch('./bubbles/meta.json').then(r => r.json()).then(setMeta).catch(() => setMeta(null)); }, []);
  const m = meta?.[`${name}_${size}`];
  const t = m?.text;
  return (
    <div className="bub" style={{ width: (m?.w ?? 196) * SCALE, height: (m?.h ?? 112) * SCALE }}>
      <img src={`./bubbles/${name}_${size}.png`} width={(m?.w ?? 196) * SCALE} height={(m?.h ?? 112) * SCALE} alt={`${name} bubble`} style={{ imageRendering: 'pixelated' }} />
      {t && <div className="btext" style={{ left: t[0] * SCALE, top: t[1] * SCALE, width: t[2] * SCALE, height: t[3] * SCALE }}>
        {size === 'full' ? <><b>{title}</b><small>{body}</small></> : <><small className="one">{title}</small>{t[3] >= 32 && <small className="two">{body}</small>}</>}
      </div>}
    </div>);
}

export function BubblesPreview() {
  return (
    <div className="pad bubbles">
      <h2>Speech bubbles</h2>
      <p className="muted">What the NU87 Home screen draws next to Usagi. These are the exact shells stored in the firmware; on the LCD the text is drawn into the same rectangle with the Pretendard glyphs.</p>
      <div className="bgrid">{STYLES.map(([n, label, title, body]) => (
        <figure key={n}><Shell name={n} size="full" title={title} body={body} /><figcaption><b>{label}</b> · {n}</figcaption></figure>))}</div>
      <h2 className="sub">Claude + Codex at the same time</h2>
      <p className="muted">Two small bubbles, one per provider, each with its own state.</p>
      <div className="bpair"><Shell name="cloud" size="half" title="Claude · 작업 중..." body="키보드 웹 UI 수정 중..." /><Shell name="burst" size="half" title="Codex · 작업 완료!" body="BLE 모듈 정리" /></div>
      <p className="muted">Gmail and other notifications use the soft bubble, Lunch uses the star. Approval, error and done have priority over notifications, notifications over “working”.</p>
    </div>);
}
